SELECT FROM iam_role WHERE deleted = FALSE
AND id IN #{item}
AND 1 = 0

SELECT 
FROM iam_role

    realm_id = #{realmId} AND deleted = FALSE
    AND role_code LIKE '%' || #{role.roleCode} || '%'
    AND role_name LIKE '%' || #{role.roleName} || '%'


            AND container_type = #{role.containerType}



            AND container_type IN ('APP', 'CLIENT')


    AND client_id = #{role.clientId}
    AND app_service_id = #{role.appServiceId}

ORDER BY id

SELECT 
FROM iam_role
WHERE realm_id = #{realmId}
  AND app_service_id = #{appServiceId}
  AND role_code = #{roleCode}
  AND deleted = FALSE
LIMIT 1

SELECT 
FROM iam_role
WHERE realm_id = #{realmId}
  AND container_type = #{containerType}
  AND role_code = #{roleCode}
  AND deleted = FALSE

    AND client_id = #{clientId}
    AND client_id IS NULL


    AND app_service_id = #{appServiceId}
    AND app_service_id IS NULL

LIMIT 1
